		both("advancement.botania:l20ShardUse", "Out of Step", "Descompasado");
		both("advancement.botania:l20ShardUse.desc", "Raise the ground up to the sky with a Power XX Shard of Laputa", "Eleva el terreno al cielo con una lasca de Laputa de poder XX");
