		both("advancement.botania:lokiRingMany.desc", "Place over 255 additional blocks at once with the Ring of Loki", "Coloca m\u00e1s de 255 bloques adicionales a la vez con el anillo de Loki");
		both("advancement.botania:luminizerRide", "World's End Dancehall", "Sal\u00f3n de baile del fin del mundo");
		both("advancement.botania:luminizerRide.desc", "Craft some Luminizers and use them for transport", "Crea algunos luminizadores y \u00fasalos para transportarte");
		same("advancement.botania:manaBlasterShoot", "M'aider Stranded Girl");
		both("advancement.botania:manaBlasterShoot.desc", "Craft and fire a Mana Blaster", "Crea y dispara una pistola de man\u00e1");
		both("advancement.botania:manaBombIgnite", "Under of Fragments", "Bajo los fragmentos");
		both("advancement.botania:manaBombIgnite.desc", "Craft a Manastorm Charge, ignite it on a far away place", "Crea una carga de tormenta de man\u00e1 y enci\u00e9ndela en un lugar lejano");
		both("advancement.botania:manaCartCraft", "World Domination How-To", "C\u00f3mo dominar el mundo");
		both("advancement.botania:manaCartCraft.desc", "Create a Minecart with Mana Pool for long range Mana transport", "Crea una vagoneta con pila de man\u00e1 para transportar man\u00e1 a larga distancia");
		both("advancement.botania:manaCookieEat", "Rotten Heresy and Chocolate", "Herej\u00eda podrida y chocolate");
		both("advancement.botania:manaCookieEat.desc", "Infuse and eat a delicious Biscuit of Totality", "Infunde y come una galleta de man\u00e1");
		both("advancement.botania:manaPoolPickup", "Vivid Wave", "Ola v\u00edvida");
		both("advancement.botania:manaPoolPickup.desc", "Craft a Mana Pool to store Mana", "Actualiza una pila de man\u00e1 diluida a una normal");
		both("advancement.botania:manaweaveArmorCraft", "Imagination Forest", "Bosque de la imaginaci\u00f3n");
		both("advancement.botania:manaweaveArmorCraft.desc", "Create Manaweave Robes to power up your Rods", "Crea una t\u00fanica de tejido de man\u00e1 para potenciar tus varas");
		both("advancement.botania:odinRing", "Lost Time Memory", "Memoria perdida en el tiempo");
		both("advancement.botania:odinRing.desc", "Be rewarded the Ring of Odin for a heroic feat", "Se recompensado con el anillo de Od\u00edn");
		both("advancement.botania:old_flower_pickup", "Deja Vu", "D\u00e9j\u00e0 vu");
		both("advancement.botania:old_flower_pickup.desc", "Discover the Daybloom Motif or Nightshade Motif", "Descubre el motivo de flor del d\u00eda o el motivo de belladona");
		both("advancement.botania:pinkinator", "Decorator", "Decorador");
		both("advancement.botania:pinkinator.desc", "Put to use The Pinkinator", "Usa el Rosanator");
		both("advancement.botania:pollidisiacPickup", "Romeo and Cinderella", "Romeo y Cenicienta");
		both("advancement.botania:pollidisiacPickup.desc", "Create a Pollidisiac; get love in the air", "Crea un polidis\u00edaco; deja que el amor flote en el aire");
		both("advancement.botania:rankSSPick", "A Tale of Six Trillion Years and a Night", "Troceador de talento");
		both("advancement.botania:rankSSPick.desc", "Dig through the world using a rank SS Terra Shatterer", "Cava a trav\u00e9s del mundo con un destructor de Terra de rango SS");
		both("advancement.botania:runePickup", "Drop Pop Candy", "Mu\u00f1eca de lilas");
		both("advancement.botania:runePickup.desc", "Use a Runic Altar to create a Rune", "Usa altar r\u00fanico para crear una runa");
		both("advancement.botania:sparkCraft", "Live Drive", "Conduce la vida");
		both("advancement.botania:sparkCraft.desc", "Make a Spark to help transfer Mana around", "Haz una chispa para transferir man\u00e1");
		both("advancement.botania:spawnerMoverUse", "I can take off my (redacted)", "\u00bfPuedo quitarme mis pant.....?");
		both("advancement.botania:spawnerMoverUse.desc", "Use a Life Aggregator to transport a Monster Spawner", "Usa un agregador de vida para transportar un generador de monstruos");
