		both("botania.page.manaAlchemy14", "Converting between $(item)Gunpowder$(0) and $(item)Flint$(0)", "Convirtiendo entre $(item)p\u00f3lvora$(0) y $(item)pedernal$(0)");
		both("botania.page.manaAlchemy15", "Conjuring $(item)Name Tags$(0)", "Haciendo $(item)etiquetas$(0)");
		both("botania.page.manaAlchemy16", "Splitting $(item)Wool$(0) into $(item)String$(0)", "Separando $(item)lana$(0) en $(item)hilo$(0)");
		both("botania.page.manaAlchemy17", "Converting between $(item)Slimeballs$(0) and $(item)Cactus$(0)", "Convirtiendo entre $(item)bolas de slime$(0) y $(item)cactus$(0)");
		both("botania.page.manaAlchemy18", "Creating $(item)Ender Pearls$(0)", "Creando $(item)perlas de enderman$(0)");
		both("botania.page.manaAlchemy19", "Converting between $(item)Glowstone$(0) and $(item)Redstone$(0)", "Convirtiendo entre $(item)piedra luminosa$(0) y $(item)redstone$(0)");
		both("botania.page.manaAlchemy20", "Breaking $(item)Cobblestone$(0) into $(item)Sand$(0)", "Rompiendo $(item)roca$(0) en $(item)arena$(0)");
		both("botania.page.manaAlchemy21", "Breaking $(item)Terracotta$(0) into $(item)Red Sand$(0)", "Rompiendo $(item)arcilla endurecida$(0) en $(item)arena roja$(0)");
		both("botania.page.manaAlchemy22", "Breaking down $(item)Clay$(0) and $(item)Bricks$(0)", "Rompiendo $(item)arcilla$(0) y $(item)ladrillos$(0)");
		both("botania.page.manaAlchemy23", "Making $(item)Coarse Dirt$(0)", "Haciendo $(item)tierra basta$(0)");
