		both("botania.page.manaAlchemy27", "Converting $(item)Chorus Fruit$(0) into $(item)Chorus Flowers$(0)", "Convirtiendo $(item)frutos de chorus$(0) en $(item)flores de chorus$(0)");
		both("botania.page.manaAlchemy28", "Converting between $(item)Apples$(0) and $(item)Berries$(0)", "Convirtiendo entre $(item)manzanas$(0) y $(item)bayas$(0)");
