		both("botania.page.manaAlchemy32", "Vines & Lily Pad", "Enredaderas y nen\u00fafar");
		both("botania.page.manaAlchemy33", "Fish", "Pez");
		both("botania.page.manaAlchemy34", "Seeds & Crops", "Semillas y cultivos");
		both("botania.page.manaAlchemy35", "Slimeball & Cactus", "Bola de slime y cactus");
