		both("botania.tater.you_came_to_the_wrong_neighborhood.0", "Six letter word just to get me along", "Una palabra de seis letras para ayudarme a seguir");
		both("botania.tater.you_came_to_the_wrong_neighborhood.1", "It's a intricacy and I'm coding on my mod and I,", "Es una complejidad y estoy programando mi mod y yo,");
		both("botania.tater.you_came_to_the_wrong_neighborhood.10", "They call me Vazki", "Me llaman Vazki");
