		both("botania.tater.you_came_to_the_wrong_neighborhood.12", "They call me Vazkki", "Me llaman Vazkki");
		both("botania.tater.you_came_to_the_wrong_neighborhood.13", "That's not my name", "Ese no es mi nombre");
		both("botania.tater.you_came_to_the_wrong_neighborhood.14", "That's not my name", "Ese no es mi nombre");
		both("botania.tater.you_came_to_the_wrong_neighborhood.15", "That's not my name", "Ese no es mi nombre");
		both("botania.tater.you_came_to_the_wrong_neighborhood.16", "That's not my name", "Ese no es mi nombre");
		both("botania.tater.you_came_to_the_wrong_neighborhood.2", "I keep fixin', and keepin' it together", "Sigo arreglando, y manteni\u00e9ndolo en orden");
		both("botania.tater.you_came_to_the_wrong_neighborhood.3", "People around gotta find something to play now", "Las personas de alrededor tiene que encontrar con qu\u00e9 jugar");
		both("botania.tater.you_came_to_the_wrong_neighborhood.4", "Holding back, every mod's the same", "Me contengo, todos los mods son iguales");
		both("botania.tater.you_came_to_the_wrong_neighborhood.5", "Don't wanna be a loser", "No quiero ser un perdedor");
		both("botania.tater.you_came_to_the_wrong_neighborhood.6", "Listen to me, oh no, I don't break anything at all", "Esc\u00fachame, oh no, nunca rompo nada en lo absoluto");
		both("botania.tater.you_came_to_the_wrong_neighborhood.7", "But with nothing to consider they forget my name", "Pero sin considerarlo se olvidan de mi nombre");
