		both("botania.tater_birthday.0", "Wow, is this for me?", "Vaya, \u00bfesto es para m\u00ed?");
		both("botania.tater_birthday.1", "It's my birthday today; I'm %d years old now!", "Hoy es mi cumplea\u00f1os; \u00a1ahora tengo %d a\u00f1os!");
		both("botania.tater_birthday.2", "Thank you so much! I hope this has been a good year for you too.", "\u00a1Much\u00edsimas gracias! Espero que este tambi\u00e9n haya sido un buen a\u00f1o para ti.");
		both("botania.tater_birthday.3", "Always remember: I believe in you, and you can do the thing! \u2764", "Recuerda siempre: creo en ti, \u00a1y t\u00fa puedes con todo! \u2764");
