	private void ponder() {
		both("botania.ponder.alfheim_portal.header", "Opening the Elven Gateway", "Abrir el acceso \u00e9lfico");
		both("botania.ponder.alfheim_portal.text_1", "The Gateway Core is built into a frame of Livingwood and Glimmering Livingwood", "El n\u00facleo de acceso se construye dentro de un marco de madera viviente y madera viviente centelleante");
		both("botania.ponder.alfheim_portal.text_2", "Two Natura Pylons, each on top of a Mana Pool with Mana in it, must stand within five blocks", "Dos pilones de Natura, cada uno sobre una pila de man\u00e1 con man\u00e1 dentro, deben estar a menos de cinco bloques");
		both("botania.ponder.alfheim_portal.text_3", "Right-click the Gateway Core with the Wand of the Forest to open it. Opening it drains Mana from the pools", "Haz clic derecho en el n\u00facleo de acceso con la varita del bosque para abrirlo. Abrirlo gasta man\u00e1 de las pilas");
		both("botania.ponder.alfheim_portal.text_4", "Throw items through the portal to trade with the elves. Two Manasteel Ingots become one Elementium Ingot", "Lanza objetos por el portal para comerciar con los elfos. Dos lingotes de manacero se convierten en un lingote de elementio");
		both("botania.ponder.gaia_ritual.header", "The Gaia Guardian Ritual", "El ritual del guardi\u00e1n de Gaia");
		both("botania.ponder.gaia_ritual.text_1", "Place a Beacon on a 3x3 platform of Iron Blocks", "Coloca un faro sobre una plataforma de 3x3 bloques de hierro");
		both("botania.ponder.gaia_ritual.text_2", "Then put a Gaia Pylon on each corner, four blocks away from the Beacon and one block higher", "Despu\u00e9s pon un pil\u00f3n de Gaia en cada esquina, a cuatro bloques del faro y un bloque m\u00e1s arriba");
		both("botania.ponder.gaia_ritual.text_3", "Clear a large arena around it, about 25x25 blocks, free of other blocks", "Despeja una gran arena alrededor, de unos 25x25 bloques, sin otros bloques");
		both("botania.ponder.gaia_ritual.text_4", "Right-click the Beacon with a Gaia Spirit to summon the Gaia Guardian", "Haz clic derecho en el faro con un esp\u00edritu de Gaia para invocar al guardi\u00e1n de Gaia");
		both("botania.ponder.mana_enchanter.header", "Enchanting with the Mana Enchanter", "Encantar con el encantador de man\u00e1");
		both("botania.ponder.mana_enchanter.text_1", "The Mana Enchanter applies enchantments to items using Mana. It stands on a platform of Obsidian, surrounded by Mystical Flowers and six Mana Pylons", "El encantador de man\u00e1 aplica encantamientos a objetos usando man\u00e1. Se levanta sobre una plataforma de obsidiana, rodeado de flores m\u00edsticas y seis pilones de man\u00e1");
		both("botania.ponder.mana_enchanter.text_2", "Place the item to enchant on the Enchanter and throw Enchanted Books with the wanted enchantments next to it", "Coloca el objeto a encantar en el encantador y lanza a su lado libros encantados con los encantamientos que quieras");
		both("botania.ponder.mana_enchanter.text_3", "Right-click the Enchanter with the Wand of the Forest to begin. The Pylons start to glow", "Haz clic derecho en el encantador con la varita del bosque para empezar. Los pilones empiezan a brillar");
		both("botania.ponder.mana_enchanter.text_4", "Spreaders must deliver the Mana the enchantments cost", "Los esparcidores deben entregar el man\u00e1 que cuestan los encantamientos");
		both("botania.ponder.mana_enchanter.text_5", "When enough Mana is gathered, the enchantments are applied to the item", "Cuando se re\u00fane suficiente man\u00e1, los encantamientos se aplican al objeto");
		both("botania.ponder.mana_pool.header", "Storing Mana in Pools", "Almacenar man\u00e1 en pilas");
		both("botania.ponder.mana_pool.text_1", "Mana Pools store up to one million units of Mana. Spreaders, Sparks and Mana Tablets can all fill them", "Las pilas de man\u00e1 almacenan hasta un mill\u00f3n de unidades de man\u00e1. Los esparcidores, las chispas y las tabletas de man\u00e1 pueden llenarlas");
		both("botania.ponder.mana_pool.text_2", "Throw items into a Pool holding enough Mana and some of them are transformed. Iron Ingots become Manasteel Ingots", "Lanza objetos a una pila con man\u00e1 suficiente y algunos se transformar\u00e1n. Los lingotes de hierro se convierten en lingotes de manacero");
		both("botania.ponder.mana_pool.text_3", "Blocks placed underneath, like the Alchemy and Conjuration Catalysts, unlock even more recipes", "Los bloques colocados debajo, como los catalizadores alqu\u00edmico y de conjuraci\u00f3n, desbloquean a\u00fan m\u00e1s recetas");
		both("botania.ponder.mana_spreader.header", "Moving Mana with Spreaders", "Mover man\u00e1 con esparcidores");
		both("botania.ponder.mana_spreader.text_1", "Generating flowers, like the Endoflame, make Mana. On their own they can only hand it to a nearby Spreader", "Las flores generadoras, como la endollama, producen man\u00e1. Por s\u00ed solas solo pueden pasarlo a un esparcidor cercano");
		both("botania.ponder.mana_spreader.text_2", "Bind the flower to the Mana Spreader with the Wand of the Forest: right-click the flower, then the Spreader", "Vincula la flor al esparcidor de man\u00e1 con la varita del bosque: clic derecho en la flor y luego en el esparcidor");
		both("botania.ponder.mana_spreader.text_3", "The Spreader fires bursts of Mana in the direction it faces", "El esparcidor dispara r\u00e1fagas de man\u00e1 en la direcci\u00f3n a la que mira");
		both("botania.ponder.mana_spreader.text_4", "A burst delivers its Mana to the first receiver it hits, such as a Mana Pool", "Una r\u00e1faga entrega su man\u00e1 al primer receptor que golpea, como una pila de man\u00e1");
		both("botania.ponder.mana_spreader.text_5", "Shift and right-click a Spreader with the Wand of the Forest to aim it. Make sure nothing blocks the way", "Ag\u00e1chate y haz clic derecho en un esparcidor con la varita del bosque para apuntarlo. Aseg\u00farate de que nada bloquee el camino");
		both("botania.ponder.petal_apothecary.header", "Crafting with the Petal Apothecary", "Fabricar con la botica de p\u00e9talos");
		both("botania.ponder.petal_apothecary.text_1", "The Petal Apothecary turns petals into Mystical Flowers and other magical items. Start by filling it with water", "La botica de p\u00e9talos convierte p\u00e9talos en flores m\u00edsticas y otros objetos m\u00e1gicos. Empieza llen\u00e1ndola de agua");
		both("botania.ponder.petal_apothecary.text_2", "Toss petals into the water. They must match a recipe, here four White Petals", "Echa p\u00e9talos al agua. Deben coincidir con una receta, aqu\u00ed cuatro p\u00e9talos blancos");
		both("botania.ponder.petal_apothecary.text_3", "Add the catalyst, usually Wheat Seeds, to finish the recipe. The water is used up", "A\u00f1ade el catalizador, normalmente semillas de trigo, para terminar la receta. El agua se gasta");
		both("botania.ponder.petal_apothecary.text_4", "The Apothecary comes in many styles, but they all work the same way", "La botica viene en muchos estilos, pero todos funcionan igual");
		both("botania.ponder.pure_daisy.header", "Purifying with the Pure Daisy", "Purificar con la margarita pura");
		both("botania.ponder.pure_daisy.text_1", "The Pure Daisy slowly transforms the eight blocks around it. It does not need any Mana", "La margarita pura transforma poco a poco los ocho bloques que la rodean. No necesita man\u00e1");
		both("botania.ponder.pure_daisy.text_2", "Stone becomes Livingrock and logs become Livingwood. Check the recipe viewer for every conversion", "La piedra se convierte en piedra viviente y los troncos en madera viviente. Consulta el visor de recetas para ver todas las conversiones");
		both("botania.ponder.runic_altar.header", "Crafting Runes at the Runic Altar", "Fabricar runas en el altar r\u00fanico");
		both("botania.ponder.runic_altar.text_1", "The Runic Altar crafts Runes. It needs Mana, so place it near a Mana Pool and a Spreader", "El altar r\u00fanico fabrica runas. Necesita man\u00e1, as\u00ed que col\u00f3calo cerca de una pila de man\u00e1 y un esparcidor");
		both("botania.ponder.runic_altar.text_2", "Throw the ingredients onto the altar. They float around it until a recipe matches", "Lanza los ingredientes sobre el altar. Flotan a su alrededor hasta que coincida una receta");
		both("botania.ponder.runic_altar.text_3", "A Spreader aimed at the altar supplies the Mana. Every recipe needs a fixed amount", "Un esparcidor apuntando al altar le da el man\u00e1. Cada receta necesita una cantidad fija");
		both("botania.ponder.runic_altar.text_4", "Once the altar is full of Mana, right-click it with Livingrock to craft. The Livingrock is consumed", "Cuando el altar est\u00e9 lleno de man\u00e1, haz clic derecho en \u00e9l con piedra viviente para fabricar. La piedra viviente se consume");
		same("botania.ponder.tag.alfheim", "Alfheim");
		both("botania.ponder.tag.alfheim.description", "Gateways to the elves and the guardians of nature", "Accesos a los elfos y guardianes de la naturaleza");
		both("botania.ponder.tag.crafting_devices", "Crafting Devices", "Dispositivos de fabricaci\u00f3n");
		both("botania.ponder.tag.crafting_devices.description", "Machines that craft items with petals, Mana and a little patience", "M\u00e1quinas que fabrican objetos con p\u00e9talos, man\u00e1 y un poco de paciencia");
		both("botania.ponder.tag.mana_network", "Mana Network", "Red de man\u00e1");
		both("botania.ponder.tag.mana_network.description", "Moving and storing Mana between blocks", "Mover y almacenar man\u00e1 entre bloques");
		both("botania.ponder.terra_plate.header", "Terrestrial Agglomeration", "Aglomeraci\u00f3n terrestre");
		both("botania.ponder.terra_plate.text_1", "The Terrestrial Agglomeration Plate sits on a base of Lapis Blocks and Livingrock", "La placa de aglomeraci\u00f3n terrestre se coloca sobre una base de bloques de lapisl\u00e1zuli y piedra viviente");
		both("botania.ponder.terra_plate.text_2", "Throw a Manasteel Ingot, a Mana Pearl and a Mana Diamond onto the plate", "Lanza un lingote de manacero, una perla de man\u00e1 y un diamante de man\u00e1 sobre la placa");
		both("botania.ponder.terra_plate.text_3", "It needs a huge amount of Mana, 500,000 units. Spreaders keep firing at it until it is full", "Necesita una enorme cantidad de man\u00e1, 500.000 unidades. Los esparcidores siguen dispar\u00e1ndole hasta que se llena");
		both("botania.ponder.terra_plate.text_4", "When the plate is full, the items fuse into a Terrasteel Ingot", "Cuando la placa est\u00e1 llena, los objetos se funden en un lingote de terracero");
		both("botania.ponder.lenses.header", "Changing Bursts with Lenses", "Cambiar las r\u00e1fagas con lentes");
		both("botania.ponder.lenses.text_1", "Lenses change how a Spreader's bursts behave. Right-click a Spreader with a lens to fit it into its lens slot", "Las lentes cambian el comportamiento de las r\u00e1fagas de un esparcidor. Haz clic derecho en un esparcidor con una lente para colocarla en su ranura");
		both("botania.ponder.lenses.text_2", "The Velocity Lens makes bursts much faster, but they carry less Mana and lose it sooner", "La lente de velocidad hace las r\u00e1fagas mucho m\u00e1s r\u00e1pidas, pero llevan menos man\u00e1 y lo pierden antes");
		both("botania.ponder.lenses.text_3", "The Potency Lens doubles the Mana in every burst, at the cost of speed. Good for big machines", "La lente de potencia duplica el man\u00e1 de cada r\u00e1faga a costa de la velocidad. Buena para m\u00e1quinas grandes");
		both("botania.ponder.lenses.text_4", "The Bounce Lens makes bursts rebound off solid blocks instead of stopping, so they can reach receivers around corners", "La lente de rebote hace que las r\u00e1fagas reboten en los bloques s\u00f3lidos en lugar de detenerse, as\u00ed llegan a receptores situados tras una esquina");
		both("botania.ponder.lenses.text_5", "There are many more: Kindle sets fire, Flash makes light, Force pushes blocks, Magnetizing homes in on receivers, Gravity makes bursts fall. Check each lens in the recipe viewer", "Hay muchas m\u00e1s: la de encendido prende fuego, la de destello crea luz, la de fuerza empuja bloques, la magnetizante busca receptores, la de gravedad hace caer las r\u00e1fagas. Consulta cada lente en el visor de recetas");
		both("botania.ponder.mana_prism.header", "Sending Bursts through a Mana Prism", "Enviar r\u00e1fagas a trav\u00e9s de un prisma de man\u00e1");
		both("botania.ponder.mana_prism.text_1", "A Mana Prism never blocks a burst: bursts fly straight through it, so it can sit right in the path of a Spreader", "Un prisma de man\u00e1 nunca bloquea una r\u00e1faga: las r\u00e1fagas lo atraviesan en l\u00ednea recta, as\u00ed que puede estar justo en el camino de un esparcidor");
		both("botania.ponder.mana_prism.text_2", "Right-click the Prism with a lens to put it inside. Every burst crossing it takes that lens's effect and turns white. Here a Velocity Lens speeds the burst up", "Haz clic derecho en el prisma con una lente para meterla dentro. Cada r\u00e1faga que lo cruza adopta el efecto de esa lente y se vuelve blanca. Aqu\u00ed una lente de velocidad acelera la r\u00e1faga");
		both("botania.ponder.mana_prism.text_3", "A Redstone signal switches the lens off, and bursts cross the Prism unchanged", "Una se\u00f1al de redstone apaga la lente y las r\u00e1fagas cruzan el prisma sin cambios");
		both("botania.ponder.mana_detector.header", "Detecting Bursts with the Mana Detector", "Detectar r\u00e1fagas con el detector de man\u00e1");
		both("botania.ponder.mana_detector.text_1", "The Mana Detector reacts to every burst passing through it. The burst is not stopped and keeps flying to its target", "El detector de man\u00e1 reacciona a cada r\u00e1faga que lo atraviesa. La r\u00e1faga no se detiene y sigue volando hacia su destino");
		both("botania.ponder.mana_detector.text_2", "Each burst makes the Detector emit a short Redstone pulse, enough to light a lamp or trigger a circuit", "Cada r\u00e1faga hace que el detector emita un pulso corto de redstone, suficiente para encender una l\u00e1mpara o activar un circuito");
		both("botania.ponder.mana_detector.text_3", "Use it to know when a Spreader is working, to count bursts, or to start a machine only when Mana is flowing", "\u00dasalo para saber cu\u00e1ndo funciona un esparcidor, para contar r\u00e1fagas o para arrancar una m\u00e1quina solo cuando fluye man\u00e1");
		both("botania.ponder.mana_sparks.header", "Moving Mana with Sparks", "Mover man\u00e1 con chispas");
		both("botania.ponder.mana_sparks.text_1", "Sparks move Mana without Spreaders. Right-click a Mana Pool, a Mana Enchanter or a Terrestrial Agglomeration Plate with a Spark to place one above it", "Las chispas mueven man\u00e1 sin esparcidores. Haz clic derecho en una pila de man\u00e1, un encantador de man\u00e1 o una placa de aglomeraci\u00f3n terrestre con una chispa para colocarla encima");
		both("botania.ponder.mana_sparks.text_2", "Put a Spark on the machine too. While the machine is crafting, it draws Mana from the Pools that have a Spark within twelve blocks", "Pon tambi\u00e9n una chispa en la m\u00e1quina. Mientras fabrica, toma man\u00e1 de las pilas que tengan una chispa a menos de doce bloques");
		both("botania.ponder.mana_sparks.text_3", "Right-click a Spark with Dye to colour it. Sparks only link with Sparks of the same colour, so you can keep separate networks", "Haz clic derecho en una chispa con tinte para colorearla. Las chispas solo se enlazan con otras del mismo color, as\u00ed puedes mantener redes separadas");
		both("botania.ponder.mana_sparks.text_4", "Right-click a Spark with the Wand of the Forest to see its network. Sneak-click to take the Spark back", "Haz clic derecho en una chispa con la varita del bosque para ver su red. Con clic derecho agachado recuperas la chispa");
		both("botania.ponder.spark_augments.header", "Spark Augments", "Aumentos de chispa");
		both("botania.ponder.spark_augments.text_1", "Spark Augments change what a Spark does. Right-click a Spark with an augment to apply it. The Wand of the Forest removes it again", "Los aumentos de chispa cambian lo que hace una chispa. Haz clic derecho en una chispa con un aumento para aplic\u00e1rselo. La varita del bosque lo quita de nuevo");
		both("botania.ponder.spark_augments.text_2", "A Recessive Spark pushes the Mana of its Pool into the Pools of ordinary and Dispersive Sparks", "Una chispa recesiva empuja el man\u00e1 de su pila hacia las pilas de las chispas normales y dispersivas");
		both("botania.ponder.spark_augments.text_3", "A Dominant Spark does the opposite: it pulls Mana from the Pools of ordinary Sparks into its own Pool", "Una chispa dominante hace lo contrario: toma man\u00e1 de las pilas de chispas normales y lo lleva a su propia pila");
		both("botania.ponder.spark_augments.text_4", "A Dispersive Spark hands its Pool's Mana to Mana items carried by nearby players, such as Mana Tablets", "Una chispa dispersiva entrega el man\u00e1 de su pila a los objetos de man\u00e1 que lleven los jugadores cercanos, como las tabletas de man\u00e1");
		both("botania.ponder.spark_augments.text_5", "An Isolated Spark is left out of every transfer, so it never gives or takes Mana from the others", "Una chispa aislada queda fuera de todas las transferencias, as\u00ed que nunca da ni toma man\u00e1 de las dem\u00e1s");
		both("botania.ponder.generating_flowers.header", "Generating Flowers", "Flores generadoras");
		both("botania.ponder.generating_flowers.text_1", "Generating flowers make Mana by themselves. Each one needs something different to work, and none of them can store much Mana", "Las flores generadoras producen man\u00e1 por s\u00ed solas. Cada una necesita algo distinto para funcionar y ninguna puede almacenar mucho man\u00e1");
		both("botania.ponder.generating_flowers.text_2", "The Endoflame burns fuel such as Coal that lies on the ground around it", "La endollama quema combustible, como carb\u00f3n, que est\u00e9 en el suelo a su alrededor");
		both("botania.ponder.generating_flowers.text_3", "Bind the flower to a Spreader with the Wand of the Forest. The Spreader collects the Mana and fires it at a Pool or any other receiver", "Vincula la flor a un esparcidor con la varita del bosque. El esparcidor recoge el man\u00e1 y lo dispara hacia una pila u otro receptor");
		both("botania.ponder.generating_flowers.text_4", "The Hydroangeas drinks the water around it, and rests for a while between drinks. Place water next to it", "La hidrortensia bebe el agua que la rodea y descansa un rato entre trago y trago. Coloca agua a su lado");
		both("botania.ponder.generating_flowers.text_5", "Many others exist: the Thermalily burns lava, the Gourmaryllis eats food, the Entropinnyum feeds on explosions. Read each one in the Lexicon", "Existen muchas m\u00e1s: la termolila quema lava, la gurmerilia come comida, el entropinio se alimenta de explosiones. Lee cada una en la Lexica Botania");
		both("botania.ponder.functional_flowers.header", "Functional Flowers", "Flores funcionales");
		both("botania.ponder.functional_flowers.text_1", "Functional flowers work for you. The Orechid turns stone into ore, the Rannuncarpus places blocks, the Bellethorn hurts nearby creatures, and many more", "Las flores funcionales trabajan para ti. La menarqu\u00eddea convierte piedra en mena, el ranuncarpo coloca bloques, la bellap\u00faa da\u00f1a a las criaturas cercanas, y muchas m\u00e1s");
		both("botania.ponder.functional_flowers.text_2", "Most of them need Mana to work. Aim a Spreader at the flower, or bind the flower to a Mana Pool, to keep it supplied", "La mayor\u00eda necesita man\u00e1 para funcionar. Apunta un esparcidor a la flor, o vinc\u00fala a una pila de man\u00e1, para mantenerla abastecida");
		both("botania.ponder.functional_flowers.text_3", "Every flower only acts inside an area around it. Holding the Wand of the Forest while looking at a flower shows that area", "Cada flor solo act\u00faa dentro de una zona a su alrededor. Si miras una flor con la varita del bosque en la mano, ver\u00e1s esa zona");
		both("botania.ponder.functional_flowers.text_4", "The Orechid slowly turns stone in its area into ore, and spends a lot of Mana every time", "La menarqu\u00eddea convierte poco a poco la piedra de su zona en mena y gasta mucho man\u00e1 cada vez");
		both("botania.ponder.functional_flowers.text_5", "Mini versions of some flowers work in a smaller area, and floating versions can hover wherever you want", "Las versiones mini de algunas flores funcionan en una zona menor, y las versiones flotantes pueden flotar donde quieras");
		both("botania.ponder.botanical_brewery.header", "Brewing with the Botanical Brewery", "Elaborar brebajes con el fermentador bot\u00e1nico");
		both("botania.ponder.botanical_brewery.text_1", "The Botanical Brewery makes potions with Mana. Start by putting an empty Managlass Vial on it", "El fermentador bot\u00e1nico prepara pociones con man\u00e1. Empieza poniendo encima un vial de manacristal vac\u00edo");
		both("botania.ponder.botanical_brewery.text_2", "Then add the ingredients, one by one. A brew of Speed needs Nether Wart, Sugar and Redstone. Each brew has its own recipe", "Despu\u00e9s a\u00f1ade los ingredientes, uno a uno. Un brebaje de velocidad necesita verruga del Nether, az\u00facar y redstone. Cada brebaje tiene su propia receta");
		both("botania.ponder.botanical_brewery.text_3", "The Brewery needs Mana to finish, so aim a Spreader at it or place a Pool next to it", "El fermentador necesita man\u00e1 para terminar, as\u00ed que apunta un esparcidor hacia \u00e9l o col\u00f3cale una pila al lado");
		both("botania.ponder.botanical_brewery.text_4", "When it has enough Mana, the Brewery fills the vial and pops it out. Drink it to get the effect", "Cuando tiene suficiente man\u00e1, el fermentador llena el vial y lo expulsa. B\u00e9belo para obtener el efecto");
		both("botania.ponder.botanical_brewery.text_5", "Until the brew starts, right-click the Brewery with an empty hand to take the items back", "Antes de que empiece el brebaje, haz clic derecho en el fermentador con la mano vac\u00eda para recuperar los objetos");
		both("botania.ponder.catalysts.header", "Mana Pool Catalysts", "Catalizadores de la pila de man\u00e1");
		both("botania.ponder.catalysts.text_1", "A Catalyst placed directly under a Mana Pool unlocks new Mana recipes. The Alchemy Catalyst transmutes items: here, Cobblestone becomes Sand", "Un catalizador colocado justo debajo de una pila de man\u00e1 desbloquea nuevas recetas de man\u00e1. El catalizador alqu\u00edmico transmuta objetos: aqu\u00ed, el adoqu\u00edn se convierte en arena");
		both("botania.ponder.catalysts.text_2", "The Conjuration Catalyst duplicates some items, like Coal, but costs far more Mana", "El catalizador de conjuraci\u00f3n duplica algunos objetos, como el carb\u00f3n, pero cuesta mucho m\u00e1s man\u00e1");
		both("botania.ponder.catalysts.text_3", "Each recipe only works with its own Catalyst. Check the recipe viewer to see them all", "Cada receta solo funciona con su propio catalizador. Consulta el visor de recetas para verlas todas");
		both("botania.ponder.corporea_network.header", "Corporea Networks", "Redes de corporea");
		both("botania.ponder.corporea_network.text_1", "Corporea moves items instantly through a network of Corporea Sparks. Put a Corporea Spark above every chest or other inventory", "Corporea mueve objetos al instante por una red de chispas de corporea. Pon una chispa de corporea encima de cada cofre u otro inventario");
		both("botania.ponder.corporea_network.text_2", "Every network needs one Master Corporea Spark. It cannot read its own inventory, so place it on a block without one, like a Corporea Block", "Cada red necesita una chispa maestra de corporea. No puede leer su propio inventario, as\u00ed que col\u00f3cala sobre un bloque sin inventario, como un bloque de corporea");
		both("botania.ponder.corporea_network.text_3", "Sparks link with the ones within about eight blocks of them, and the network can be extended much further by chaining Sparks", "Las chispas se enlazan con las que est\u00e1n a unos ocho bloques, y la red puede extenderse mucho m\u00e1s encadenando chispas");
		both("botania.ponder.corporea_network.text_4", "A Corporea Spark above a Corporea Index connects it to the network. Stand close to the Index and say the name of an item in chat, like iron ingot", "Una chispa de corporea sobre un \u00edndice de corporea lo conecta a la red. Ac\u00e9rcate al \u00edndice y di en el chat el nombre de un objeto, como lingote de hierro");
		both("botania.ponder.corporea_network.text_5", "The Index asks the network for the item and it pops out next to the Index", "El \u00edndice pide el objeto a la red y este sale junto al \u00edndice");
		both("botania.ponder.corporea_network.text_6", "Corporea Sparks of different colours do not link, so several networks can share the same area", "Las chispas de corporea de distinto color no se enlazan, as\u00ed que varias redes pueden compartir la misma zona");
		both("botania.ponder.corporea_funnel.header", "Requesting Items with the Corporea Funnel", "Pedir objetos con el embudo de corporea");
		both("botania.ponder.corporea_funnel.text_1", "The Corporea Funnel asks a Corporea network for an item whenever it receives a Redstone signal. Put a Corporea Spark above it", "El embudo de corporea pide un objeto a una red de corporea cada vez que recibe una se\u00f1al de redstone. Pon una chispa de corporea encima");
		both("botania.ponder.corporea_funnel.text_2", "Hang an Item Frame with the wanted item on the Funnel. Rotating the item sets the amount: 1, 2, 4, 8, 16, 32, 48 or 64", "Cuelga un marco con el objeto deseado en el embudo. Girar el objeto fija la cantidad: 1, 2, 4, 8, 16, 32, 48 o 64");
		both("botania.ponder.corporea_funnel.text_3", "The item goes into an inventory one or two blocks below the Funnel, or is dropped if there is none", "El objeto va a un inventario situado uno o dos bloques bajo el embudo, o se suelta si no hay ninguno");
		both("botania.ponder.tag.flowers", "Flowers", "Flores");
		both("botania.ponder.tag.flowers.description", "Flowers that make Mana and flowers that work for you", "Flores que producen man\u00e1 y flores que trabajan para ti");
		both("botania.ponder.tag.corporea", "Corporea", "Corporea");
		both("botania.ponder.tag.corporea.description", "Moving items instantly through a network of Sparks", "Mover objetos al instante por una red de chispas");
	}

