	private void extrasLexicon() {
		same("botania.category.botania_extras", "Botania Extras");
		both("botania.category.botania_extras.description", "Iridescent soils, rainbow plants and other curiosities, adapted from the Botanical Addons mod by L0neKitsune and WireSegal.", "Tierras iridiscentes, plantas arco\u00edris y otras curiosidades, adaptadas del mod Botanical Addons de L0neKitsune y WireSegal.");
		both("botania.entry.iridescentDirt", "Iridescent Dirt", "Tierra iridiscente");
		both("botania.tagline.iridescentDirt", "Rainbow dirt for your decoration needs", "Tierra arco\u00edris para decorar");
		both("botania.page.iridescentDirt0", "Using the latent power in $(item)Mystical Flowers$(0), you can make dirt that shimmers every color of the rainbow. This mystical dirt is capable of growing trees and plants without water or a hoe. If put next to a $(item)Pure Daisy$(0), it will revert to its uncolored state.", "Usando el poder latente de las $(item)Flores m\u00edsticas$(0), puedes crear tierra que brilla con todos los colores del arco\u00edris. Esta tierra m\u00edstica puede hacer crecer \u00e1rboles y plantas sin agua ni azada. Si se coloca junto a una $(item)Margarita pura$(0), vuelve a su estado sin color.");
		both("botania.page.iridescentDirt1", "Beauty from the dross", "Belleza a partir de la escoria");
		both("botania.page.iridescentDirt2", "The $(thing)Bifrost$(0) variant is made with $(item)Floral Bifrost Powder$(0) or a $(item)Bifrost Block$(0) instead of a dye.", "La variante $(thing)Bifrost$(0) se hace con $(item)Polvo floral Bifrost$(0) o un $(item)Bloque Bifrost$(0) en lugar de un tinte.");
		both("botania.entry.iridescentGrass", "Iridescent Grass", "Hierba iridiscente");
		both("botania.tagline.iridescentGrass", "Rainbow grass for your colorful landscapes", "Hierba arco\u00edris para paisajes coloridos");
		both("botania.page.iridescentGrass0", "If $(item)Bone Meal$(0) is used on $(item)Iridescent Dirt$(0), it will grow $(item)Iridescent Grass$(0) instead of $(item)Tall Grass$(0). When this $(item)Iridescent Grass$(0) is thrown into a $(thing)Mana Pool$(0), you get out something quite like the $(item)Pasture Seed$(0). It will transmute $(item)Grass$(0) and $(item)Dirt$(0) into $(item)Iridescent Dirt$(0), with a simple right click.", "Si usas $(item)Polvo de hueso$(0) sobre $(item)Tierra iridiscente$(0), crecer\u00e1 $(item)Hierba iridiscente$(0) en vez de $(item)Hierba alta$(0). Al arrojar esta $(item)Hierba iridiscente$(0) a una $(thing)Pila de man\u00e1$(0) obtienes algo muy parecido a las $(item)Semillas de pasto$(0): con un simple clic derecho transforman $(item)Hierba$(0) y $(item)Tierra$(0) en $(item)Tierra iridiscente$(0).");
		both("botania.page.iridescentGrass1", "Tiger Orchid monoculture", "Monocultivo de orqu\u00eddeas tigre");
		both("botania.page.iridescentGrass2", "Crafting any $(item)Iridescent Grass$(0) with $(item)Redstone$(0) yields a $(item)Redstone Root$(0).", "Combinar cualquier $(item)Hierba iridiscente$(0) con $(item)Redstone$(0) da una $(item)Ra\u00edz de redstone$(0).");
		both("botania.entry.bifrostFlowers", "Bifrost Flora", "Flora Bifrost");
		both("botania.tagline.bifrostFlowers", "Every color at once", "Todos los colores a la vez");
		both("botania.page.bifrostFlowers0", "Sprinkling $(item)Floral Bifrost Powder$(0) on a $(item)Mystical Flower$(0), by hand or with a $(item)Dispenser$(0), turns it into a $(item)Mystical Bifrost Flower$(0). $(item)Bone Meal$(0) makes it grow tall.$(p)Used on a $(item)Mana Pool$(0), the powder turns it into a $(item)Fabulous Mana Pool$(0), keeping its $(thing)Mana$(0).", "Espolvorear $(item)Polvo floral Bifrost$(0) sobre una $(item)Flor m\u00edstica$(0), a mano o con un $(item)Dispensador$(0), la convierte en una $(item)Flor m\u00edstica Bifrost$(0). El $(item)Polvo de hueso$(0) la hace crecer alta.$(p)Usado sobre una $(item)Pila de man\u00e1$(0), el polvo la convierte en una $(item)Pila de man\u00e1 fabulosa$(0), conservando su $(thing)man\u00e1$(0).");
		both("botania.page.bifrostFlowers1", "Petals of the rainbow", "P\u00e9talos del arco\u00edris");
		both("botania.page.bifrostFlowers2", "$(item)Mystical Bifrost Petals$(0) can stand in for any petal in the $(item)Petal Apothecary$(0), $(item)Mana Spreader$(0) and $(item)Flower Pouch$(0) recipes, and grind into $(item)Floral Bifrost Powder$(0).", "Los $(item)P\u00e9talos m\u00edsticos Bifrost$(0) sirven como cualquier p\u00e9talo en las recetas de la $(item)Botica de p\u00e9talos$(0), el $(item)Esparcidor de man\u00e1$(0) y la $(item)Bolsa de flores$(0), y se muelen en $(item)Polvo floral Bifrost$(0).");
		both("botania.page.bifrostFlowers3", "Infusing the powder in a $(thing)Mana Pool$(0) yields $(item)Mana Powder$(0), and it can replace the $(item)Bifrost Block$(0) in $(item)Shimmerrock$(0) and $(item)Shimmerwood Planks$(0).", "Infundir el polvo en una $(thing)Pila de man\u00e1$(0) da $(item)Polvo de man\u00e1$(0), y puede reemplazar al $(item)Bloque Bifrost$(0) en la $(item)Roca tornasol$(0) y los $(item)Tablones de madera tornasol$(0).");
		both("botania.entry.iridescentLantern", "Iridescent Lantern", "Farol iridiscente");
		both("botania.tagline.iridescentLantern", "A signal-strength tester", "Un medidor de se\u00f1al");
		both("botania.page.iridescentLantern0", "The $(item)Iridescent Lantern$(0) glows with all the colors of the rainbow. While black in appearance when first set down, giving it a redstone signal will change its color. The higher the signal, the farther down the rainbow the color becomes.$(p)If given a full signal, the $(item)Iridescent Lantern$(0) will glow like the $(thing)Bifrost$(0) itself.", "El $(item)Farol iridiscente$(0) brilla con todos los colores del arco\u00edris. Al colocarlo se ve negro, pero una se\u00f1al de redstone cambia su color: cuanto m\u00e1s fuerte la se\u00f1al, m\u00e1s avanza por el arco\u00edris.$(p)Con una se\u00f1al completa, el $(item)Farol iridiscente$(0) brilla como el propio $(thing)Bifrost$(0).");
		both("botania.page.iridescentLantern1", "Left by a Piggah", "Dejado por un Piggah");
		both("botania.entry.frozenStar", "Frozen Stars", "Estrellas congeladas");
		both("botania.tagline.frozenStar", "An ender light source", "Una fuente de luz del End");
		both("botania.page.frozenStar0", "The $(item)Frozen Star$(0) is the light of the stars, trapped upon earth. They are relatively cheap light sources, and give off light with the same strength as $(item)Glowstone$(0). Due to their instability, they can only be harvested by players.", "La $(item)Estrella congelada$(0) es la luz de las estrellas atrapada en la tierra. Es una fuente de luz relativamente barata que ilumina con la misma fuerza que la $(item)Piedra luminosa$(0). Por su inestabilidad, solo los jugadores pueden recogerla.");
		both("botania.page.frozenStar1", "Find Polaris to find your way", "Busca la Polar para encontrar tu camino");
		both("botania.entry.blazeKindling", "Blaze Kindling", "Yesca de blaze");
		both("botania.tagline.blazeKindling", "Quickened firespread", "Fuego que se propaga r\u00e1pido");
		both("botania.page.blazeKindling0", "$(item)Blaze Kindling$(0) is like $(item)Netherrack$(0) on steroids. Not only will it sustain flames, but it will take them in from nearby blocks, very quickly. It can also be extinguished and lit simply by using it with an open hand.", "La $(item)Yesca de blaze$(0) es como una $(item)Netherrack$(0) con esteroides. No solo mantiene las llamas, sino que las atrae de los bloques cercanos muy r\u00e1pido. Tambi\u00e9n se puede encender y apagar simplemente us\u00e1ndola con la mano vac\u00eda.");
		both("botania.page.blazeKindling1", "Stop drop and roll", "Detente, t\u00edrate y rueda");
		both("botania.entry.shimmerquartz", "Shimmerquartz", "Cuarzo tornasol");
		both("botania.tagline.shimmerquartz", "Quartz but rainbow", "Cuarzo, pero arco\u00edris");
		both("botania.page.shimmerquartz0", "$(item)Nether Quartz$(0) surrounding a bifrost dye takes on its colors, becoming $(item)Shimmerquartz$(0). Like other quartz, it can be shaped into blocks, pillars, slabs and stairs.", "El $(item)Cuarzo del Nether$(0) que rodea un tinte Bifrost toma sus colores y se convierte en $(item)Cuarzo tornasol$(0). Como otros cuarzos, se puede convertir en bloques, pilares, losas y escaleras.");
		both("botania.page.shimmerquartz1", "Quartz but rainbow", "Cuarzo, pero arco\u00edris");
		both("botania.page.shimmerquartz2", "Shimmerquartz decor", "Decoraci\u00f3n de cuarzo tornasol");
		both("botania.entry.iridescentSapling", "Iridescent Sapling", "Brote iridiscente");
		both("botania.tagline.iridescentSapling", "Trees in every color of the rainbow", "\u00c1rboles de todos los colores del arco\u00edris");
		both("botania.page.iridescentSapling0", "A $(item)Pure Daisy$(0) will turn any $(item)Sapling$(0) into an $(item)Iridescent Sapling$(0). Planted on $(item)Iridescent Dirt$(0) it grows into a tree of the same color, and $(item)Bone Meal$(0) speeds it along. The $(thing)Bifrost$(0) variety grows on $(item)Bifrost Dirt$(0).$(p)Plain dirt will not do: the sapling only grows on soil that holds the power of the rainbow.", "Una $(item)Margarita pura$(0) convierte cualquier $(item)Brote$(0) en un $(item)Brote iridiscente$(0). Plantado sobre $(item)Tierra iridiscente$(0) crece como un \u00e1rbol del mismo color, y el $(item)Polvo de hueso$(0) lo acelera. La variedad $(thing)Bifrost$(0) crece sobre $(item)Tierra Bifrost$(0).$(p)La tierra com\u00fan no sirve: el brote solo crece en suelos que guardan el poder del arco\u00edris.");
		both("botania.page.iridescentSapling1", "On $(item)Dry$(0), $(item)Golden$(0), $(item)Vivid$(0), $(item)Scorched$(0), $(item)Infused$(0) and $(item)Mutated Grass$(0) the same sapling grows into a tree of matching wood. Their leaves drop saplings much less often.", "Sobre $(item)Hierba seca$(0), $(item)dorada$(0), $(item)v\u00edvida$(0), $(item)chamuscada$(0), $(item)infundida$(0) y $(item)mutada$(0) el mismo brote crece como un \u00e1rbol de la madera correspondiente. Sus hojas sueltan brotes con mucha menos frecuencia.");
		both("botania.page.iridescentSapling2", "Leaves of an iridescent tree can be crushed into $(item)Dye$(0) of their color, and $(thing)Bifrost$(0) leaves into $(item)Floral Bifrost Powder$(0). Leaves also drop new saplings.", "Las hojas de un \u00e1rbol iridiscente se pueden moler para obtener $(item)Tinte$(0) de su color, y las hojas $(thing)Bifrost$(0) dan $(item)Polvo floral Bifrost$(0). Las hojas tambi\u00e9n sueltan nuevos brotes.");
		both("botania.entry.iridescentWood", "Iridescent Wood", "Madera iridiscente");
		both("botania.tagline.iridescentWood", "Rainbow timber", "Madera del arco\u00edris");
		both("botania.page.iridescentWood0", "The logs of every iridescent and alternative tree can be turned into planks, slabs and stairs. Iridescent wood takes its color from the dirt it grew on. Logs burn as fuel and smelt into charcoal.", "Los troncos de todos los \u00e1rboles iridiscentes y alternativos se pueden convertir en tablones, losas y escaleras. La madera iridiscente toma el color de la tierra en la que creci\u00f3. Los troncos sirven de combustible y se funden en carb\u00f3n vegetal.");
		both("botania.page.iridescentWood1", "Wood from every color", "Madera de todos los colores");
		both("botania.page.iridescentWood2", "Slabs of every wood", "Losas de todas las maderas");
		both("botania.page.iridescentWood3", "Stairs of every wood", "Escaleras de todas las maderas");
		both("botania.entry.vibrantPlainsRod", "Rod of the Vibrant Plains", "Vara de las llanuras vibrantes");
		both("botania.tagline.vibrantPlainsRod", "Rainbow dirt made from thin air", "Tierra arco\u00edris salida de la nada");
		both("botania.page.vibrantPlainsRod0", "The $(item)Rod of the Vibrant Plains$(0), like the $(item)Rod of the Highlands$(0), can place $(item)Iridescent Dirt$(0) in the air at the cost of mana. Unlike its less colorful counterpart, sneaking and using it in the air shifts the rod between the colors of $(thing)Iridescence$(0).$(p)This rod can be given to a $(item)Livingwood Avatar$(0).", "La $(item)Vara de las llanuras vibrantes$(0), igual que la $(item)Vara de las tierras altas$(0), puede colocar $(item)Tierra iridiscente$(0) en el aire a cambio de man\u00e1. A diferencia de su prima menos colorida, agacharte y usarla en el aire cambia la vara entre los colores de la $(thing)Iridiscencia$(0).$(p)Esta vara se le puede dar a un $(item)Avatar de madera viviente$(0).");
		both("botania.page.vibrantPlainsRod1", "Simply drowning in colors", "Ahog\u00e1ndote en colores");
		both("botania.page.vibrantPlainsRod2", "Connecting your soul to the ancient god of earth, $(thing)Sif$(0), can increase your ability to use the $(item)Rod of the Vibrant Plains$(0). By donning the $(item)Priestly Emblem: Sif$(0), your range extends beyond this rod's normal limits. Wearing the $(item)Ring of Far Reach$(0) increases it further.", "Conectar tu alma con el antiguo dios de la tierra, $(thing)Sif$(0), puede mejorar tu manejo de la $(item)Vara de las llanuras vibrantes$(0). Al llevar el $(item)Emblema sacerdotal: Sif$(0), tu alcance supera el l\u00edmite normal de la vara. El $(item)Anillo de largo alcance$(0) lo aumenta todav\u00eda m\u00e1s.");
		both("botania.entry.thunderingPeaksRod", "Rod of the Thundering Peaks", "Vara de las cumbres tronantes");
		both("botania.tagline.thunderingPeaksRod", "Strike fear and thunder into your foes", "Siembra el miedo y el trueno entre tus enemigos");
		both("botania.page.thunderingPeaksRod0", "The $(item)Rod of the Thundering Peaks$(0), much like its sword cousin the $(item)Thundercaller$(0), can summon lightning to strike your enemies. Hold it to charge a bolt: it will leap from enemy to enemy, hitting them all in turn.$(p)A $(item)Livingwood Avatar$(0) can also wield this rod.", "La $(item)Vara de las cumbres tronantes$(0), igual que su prima la espada $(item)Thundercaller$(0), puede invocar rayos contra tus enemigos. Mantenla pulsada para cargar un rayo: saltar\u00e1 de enemigo en enemigo, golpe\u00e1ndolos a todos por turnos.$(p)Un $(item)Avatar de madera viviente$(0) tambi\u00e9n puede empu\u00f1ar esta vara.");
		both("botania.page.thunderingPeaksRod1", "The experimental results are shocking", "Los resultados del experimento son impactantes");
		both("botania.page.thunderingPeaksRod2", "Connecting your soul to the ancient god of lightning, $(thing)Thor$(0), improves your proficiency with the power of thunder. This can be achieved by donning the $(item)Priestly Emblem: Thor$(0). Wearing the $(item)Manaweave Cowl$(0) has a similar effect on the rod.$(p)There seems to be even more power trapped within it, but it would take a god to get it out.", "Conectar tu alma con el antiguo dios del rayo, $(thing)Thor$(0), mejora tu dominio del poder del trueno. Se logra llevando el $(item)Emblema sacerdotal: Thor$(0). Llevar la $(item)Capucha de tejido de man\u00e1$(0) tiene un efecto parecido sobre la vara.$(p)Parece que hay todav\u00eda m\u00e1s poder atrapado en ella, pero har\u00eda falta un dios para sacarlo.");
		both("botania.entry.stormySeaRod", "Rod of the Stormy Sea", "Vara del mar tormentoso");
		both("botania.tagline.stormySeaRod", "Push enemies out of your personal space", "Aparta a los enemigos de tu espacio personal");
		both("botania.page.stormySeaRod0", "The $(item)Rod of the Stormy Sea$(0) is one for those who don't like people in their personal space. Using it seals the area around you, creating a sphere of force where living beings cannot tread and projectiles cannot pass. Whenever something tries to break this seal, $(thing)Mana$(0) is consumed to repel it.$(p)A $(item)Livingwood Avatar$(0) can also wield this rod.", "La $(item)Vara del mar tormentoso$(0) es para quienes no soportan que invadan su espacio personal. Al usarla sella el \u00e1rea a tu alrededor y crea una esfera de fuerza por la que los seres vivos no pueden pasar ni los proyectiles atravesar. Cada vez que algo intenta romper el sello se consume $(thing)man\u00e1$(0) para repelerlo.$(p)Un $(item)Avatar de madera viviente$(0) tambi\u00e9n puede empu\u00f1ar esta vara.");
		both("botania.page.stormySeaRod1", "Really not feeling up to it right now", "Hoy no tengo ganas de nada");
		both("botania.page.stormySeaRod2", "Connecting your soul to the ancient god of wind, $(thing)Njord$(0), improves your proficiency with the power of air. By donning the $(item)Priestly Emblem: Njord$(0), the force you exert with this rod becomes much greater. Wearing the $(item)Manaweave Cowl$(0) has a similar, but weaker, effect.", "Conectar tu alma con el antiguo dios del viento, $(thing)Njord$(0), mejora tu dominio del poder del aire. Al llevar el $(item)Emblema sacerdotal: Njord$(0), la fuerza que ejerces con esta vara es mucho mayor. Llevar la $(item)Capucha de tejido de man\u00e1$(0) tiene un efecto parecido, aunque m\u00e1s d\u00e9bil.");
		both("botania.entry.prismaticLakeRod", "Rod of the Prismatic Lake", "Vara del lago prism\u00e1tico");
		both("botania.tagline.prismaticLakeRod", "Rainbow lights", "Luces del arco\u00edris");
		both("botania.page.prismaticLakeRod0", "One particularly frustrating property of the $(item)Flash Lens$(0) is its tendency to lock the color of a $(item)Mana Flash$(0) as soon as it is made. Even if you want a rainbow flash, you get a single color. The $(item)Rod of the Prismatic Lake$(0) places the rainbow you have been searching for. Use it on a flash to put it out.$(p)It can be tinged with $(item)Phantom Ink$(0), hiding the flashes from anyone without a $(item)Manaseer Monocle$(0).", "Una propiedad especialmente frustrante de la $(item)Lente de destello$(0) es que fija el color del $(item)Destello de man\u00e1$(0) en cuanto se crea. Aunque quieras un destello arco\u00edris, solo obtienes un color. La $(item)Vara del lago prism\u00e1tico$(0) coloca el arco\u00edris que buscabas. \u00dasala sobre un destello para apagarlo.$(p)Se puede te\u00f1ir con $(item)Tinta fantasma$(0), ocultando los destellos a quien no lleve un $(item)Mon\u00f3culo de manavidente$(0).");
		both("botania.page.prismaticLakeRod1", "All the colors of the wind", "Todos los colores del viento");
		both("botania.page.prismaticLakeRod2", "The $(item)Phantom Flash Lens$(0) works like the $(item)Flash Lens$(0), but leaves a $(item)Phantom Mana Flash$(0) that only those wearing a $(item)Manaseer Monocle$(0) can see. Combine a $(item)Flash Lens$(0) with $(item)Phantom Ink$(0) to make one, and do the same again to undo it.", "La $(item)Lente de destello fantasma$(0) funciona como la $(item)Lente de destello$(0), pero deja un $(item)Destello de man\u00e1 fantasma$(0) que solo ven quienes llevan un $(item)Mon\u00f3culo de manavidente$(0). Combina una $(item)Lente de destello$(0) con $(item)Tinta fantasma$(0) para fabricarla, y repite lo mismo para deshacerla.");
		both("botania.entry.priestlyEmblems", "Priestly Emblems", "Emblemas sacerdotales");
		both("botania.tagline.priestlyEmblems", "Faith has a price", "La fe tiene un precio");
		both("botania.page.priestlyEmblems0", "The $(item)Priestly Emblems$(0) bind your soul to the gods of the north. Worn as an amulet, each emblem slowly drains mana to keep your faith alive and strengthens the rod of its god: $(item)Thor$(0) for the $(item)Rod of the Thundering Peaks$(0), $(item)Sif$(0) for the $(item)Rod of the Vibrant Plains$(0) and $(item)Njord$(0) for the $(item)Rod of the Stormy Sea$(0).", "Los $(item)Emblemas sacerdotales$(0) atan tu alma a los dioses del norte. Llevado como amuleto, cada emblema consume man\u00e1 lentamente para mantener viva tu fe y fortalece la vara de su dios: $(item)Thor$(0) la $(item)Vara de las cumbres tronantes$(0), $(item)Sif$(0) la $(item)Vara de las llanuras vibrantes$(0) y $(item)Njord$(0) la $(item)Vara del mar tormentoso$(0).");
		both("botania.page.priestlyEmblems1", "A $(item)Holy Symbol$(0) holds the faith that every emblem needs.", "Un $(item)S\u00edmbolo sagrado$(0) guarda la fe que todo emblema necesita.");
		both("botania.page.priestlyEmblems2", "Priestly fashion", "Moda sacerdotal");
		both("botania.page.priestlyEmblems3", "Losing faith in the gods can be deadly. Taking off an active emblem hurts you through any armor and leaves you blinded, nauseous, slowed and weakened. Players in creative mode are spared.", "Perder la fe en los dioses puede ser mortal. Quitarte un emblema activo te hiere atravesando cualquier armadura y te deja cegado, mareado, lento y debilitado. Los jugadores en creativo se libran.");
		both("botania.entry.itemPlatform", "Item Platforms", "Plataformas de objetos");
		both("botania.tagline.itemPlatform", "Display items without letting them despawn", "Exhibe objetos sin que desaparezcan");
		both("botania.page.itemPlatform0", "The $(item)Item Platform$(0) is a neat way to display an item without having it despawn. Giving it an item via right click or hopper will show it floating above the platform; right click it again to take the item back. It is also the component that holds the ingredients of a $(thing)Dendric Suffuser$(0).", "La $(item)Plataforma de objetos$(0) es una forma pr\u00e1ctica de exhibir un objeto sin que desaparezca. Si le das un objeto con clic derecho o con una tolva, lo ver\u00e1s flotando sobre la plataforma; vuelve a hacer clic derecho para recuperarlo. Tambi\u00e9n es el componente que guarda los ingredientes de un $(thing)Infusor dendr\u00edtico$(0).");
		both("botania.page.itemPlatform1", "Terrasteel makes you look rich", "El terracero te hace parecer rico");
		both("botania.entry.treeSuffusion", "Tree Suffusion", "Infusi\u00f3n arb\u00f3rea");
		both("botania.tagline.treeSuffusion", "Infusing trees with mana and material", "Infundir a los \u00e1rboles man\u00e1 y materia");
		both("botania.page.treeSuffusion0", "Affecting life is much harder than making or destroying it. The $(item)Iridescent Sapling$(0) has a natural lack of regular life, which lends itself to making beautiful spectrums of wood. It seems possible to re-add this life by drawing mana into a $(thing)Dendric Suffuser$(0). This structure, of $(item)Obsidian$(0) and materials of $(thing)Iridescence$(0), will suffuse the sapling with life, creating interesting new varieties of trees.", "Afectar a la vida es mucho m\u00e1s dif\u00edcil que crearla o destruirla. El $(item)Brote iridiscente$(0) carece de vida corriente, lo que lo hace ideal para crear bellos espectros de madera. Parece posible devolverle esa vida atrayendo man\u00e1 a un $(thing)Infusor dendr\u00edtico$(0). Esta estructura, hecha de $(item)obsidiana$(0) y materiales de $(thing)iridiscencia$(0), impregnar\u00e1 el brote de vida y crear\u00e1 nuevas variedades de \u00e1rboles.");
		both("botania.page.treeSuffusion1", "When a $(item)Wand of the Forest$(0) is used on the apex plank of the structure, it will complete it. For a tree to be made, you must plant a lifeless $(item)Iridescent Sapling$(0) on the dirt below and pump $(thing)Mana$(0) into the apex block, for example with a $(item)Spark$(0). The components must be placed on the $(item)Item Platforms$(0), and the crafting will begin on its own.", "Cuando se usa una $(item)Varita del bosque$(0) sobre el tabl\u00f3n del v\u00e9rtice de la estructura, esta se completa. Para obtener un \u00e1rbol debes plantar un $(item)Brote iridiscente$(0) sin vida en la tierra de abajo y bombear $(thing)man\u00e1$(0) al bloque del v\u00e9rtice, por ejemplo con una $(item)Chispa$(0). Los componentes se colocan sobre las $(item)Plataformas de objetos$(0) y la creaci\u00f3n empieza sola.");
		both("botania.page.treeSuffusion2", "The Dendric Suffuser", "El Infusor dendr\u00edtico");
		both("botania.page.treeSuffusion3", "The apex block can be any $(item)Iridescent$(0) or $(thing)Bifrost$(0) plank, and the dirt any iridescent soil. The ingredients of every recipe are listed in the entries of the $(item)Thunderous Oak$(0), $(item)Infernal Oak$(0) and $(item)Sealing Oak$(0).", "El bloque del v\u00e9rtice puede ser cualquier tabl\u00f3n $(item)iridiscente$(0) o $(thing)Bifrost$(0), y la tierra cualquier suelo iridiscente. Los ingredientes de cada receta aparecen en las entradas del $(item)Roble atronador$(0), el $(item)Roble infernal$(0) y el $(item)Roble sellador$(0).");
		both("botania.entry.thunderousOak", "Thunderous Oak", "Roble atronador");
		both("botania.tagline.thunderousOak", "A lightning-absorbing tree", "Un \u00e1rbol que absorbe rayos");
		both("botania.page.thunderousOak0", "The $(item)Thunderous Oak$(0) is a tree that acts like a lightning rod. Its logs absorb natural lightning from up to 48 blocks around and redirect it to themselves. The bolt still strikes, but the fires it would light nearby are put out.", "El $(item)Roble atronador$(0) es un \u00e1rbol que act\u00faa como pararrayos. Sus troncos absorben los rayos naturales que caen hasta a 48 bloques y los atraen hacia s\u00ed. El rayo sigue cayendo, pero se apagan los fuegos que habr\u00eda prendido cerca.");
		both("botania.page.thunderousOak1", "Thor will hate you", "Thor te odiar\u00e1");
		both("botania.page.thunderousOak2", "Planks and slabs", "Tablones y losas");
		both("botania.page.thunderousOak3", "Stairs and twigs", "Escaleras y ramitas");
		both("botania.page.thunderousOak4", "The logs smelt into $(item)Charcoal$(0) and the planks into $(item)Thunderous Splinters$(0), which go into the $(item)Rod of the Thundering Peaks$(0) together with the twigs.", "Los troncos se funden en $(item)carb\u00f3n vegetal$(0) y los tablones en $(item)Astillas atronadoras$(0), que junto con las ramitas se usan en la $(item)Vara de las cumbres tronantes$(0).");
		both("botania.entry.infernalOak", "Infernal Oak", "Roble infernal");
		both("botania.tagline.infernalOak", "A fireproof tree", "Un \u00e1rbol a prueba de fuego");
		both("botania.page.infernalOak0", "The $(item)Infernal Oak$(0) is a tree so saturated with fire energy that it repulses external flames. Its leaves, logs and planks are all completely immune to conventional flames, and fire never dies out on top of its logs.", "El $(item)Roble infernal$(0) est\u00e1 tan saturado de energ\u00eda \u00edgnea que repele las llamas externas. Sus hojas, troncos y tablones son completamente inmunes al fuego convencional, y el fuego nunca se apaga sobre sus troncos.");
		both("botania.page.infernalOak1", "Just pour more fire on it, it will work eventually", "\u00c9chale m\u00e1s fuego, alg\u00fan d\u00eda funcionar\u00e1");
		both("botania.page.infernalOak2", "Planks and slabs", "Tablones y losas");
		both("botania.page.infernalOak3", "Stairs and twigs", "Escaleras y ramitas");
		both("botania.page.infernalOak4", "The logs smelt into $(item)Flame-Laced Charcoal$(0), a long-burning fuel that also makes fine torches, and the planks into $(item)Infernal Splinters$(0).", "Los troncos se funden en $(item)Carb\u00f3n vegetal con llamas$(0), un combustible de larga duraci\u00f3n que adem\u00e1s da buenas antorchas, y los tablones en $(item)Astillas infernales$(0).");
		both("botania.entry.sealingOak", "Sealing Oak", "Roble sellador");
		both("botania.tagline.sealingOak", "An extra utility", "Una utilidad extra");
		both("botania.page.sealingOak0", "The $(item)Sealing Oak$(0) has a strange dampening effect on the air around it. Any sound within eight blocks of any $(thing)Sealing$(0) wood block will be half as loud as it would have been otherwise.", "El $(item)Roble sellador$(0) tiene un extra\u00f1o efecto amortiguador sobre el aire que lo rodea. Cualquier sonido a menos de ocho bloques de un bloque de madera $(thing)selladora$(0) se oir\u00e1 a la mitad de volumen.");
		both("botania.page.sealingOak1", "Silence is golden", "El silencio es oro");
		both("botania.page.sealingOak2", "Planks and slabs", "Tablones y losas");
		both("botania.page.sealingOak3", "Stairs", "Escaleras");
		both("botania.page.sealingOak4", "The logs smelt into $(item)Charcoal$(0). Its planks are also the heart of the $(item)Sonic Amplifier$(0).", "Los troncos se funden en $(item)carb\u00f3n vegetal$(0). Sus tablones tambi\u00e9n son el coraz\u00f3n del $(item)Amplificador s\u00f3nico$(0).");
		both("botania.entry.sonicAmplifier", "Sonic Amplifier", "Amplificador s\u00f3nico");
		both("botania.tagline.sonicAmplifier", "Turn it up", "S\u00fabelo");
		both("botania.page.sonicAmplifier0", "By dampening the air within $(item)Note Blocks$(0), the $(item)Sonic Amplifier$(0) reverberates sound, making sounds within a couple of blocks far louder. The more you have, the louder the sound.", "Al amortiguar el aire del interior de los $(item)Bloques musicales$(0), el $(item)Amplificador s\u00f3nico$(0) hace reverberar el sonido y los sonidos a un par de bloques se oyen mucho m\u00e1s fuertes. Cuantos m\u00e1s pongas, m\u00e1s fuerte sonar\u00e1.");
		both("botania.page.sonicAmplifier1", "Soaryn + Amp + Cacophonium = Dire rage", "Soaryn + Amp + Cacophonium = ira terrible");
		both("botania.entry.livingwoodFunnel", "Livingwood Funnel", "Embudo de madera viviente");
		both("botania.tagline.livingwoodFunnel", "A filterable hopper that only carries one item", "Una tolva con filtro que solo lleva un objeto");
		both("botania.page.livingwoodFunnel0", "For some people, the $(item)Hopper$(0) is too lax. It allows items through when it shouldn't, and sometimes moves them too fast. The $(item)Livingwood Funnel$(0) is far, far stricter. It only allows one item through at a time, and can be filtered by placing an $(item)Item Frame$(0) on one of its sides.", "Para algunos, la $(item)Tolva$(0) es demasiado laxa: deja pasar objetos cuando no deber\u00eda y a veces los mueve demasiado r\u00e1pido. El $(item)Embudo de madera viviente$(0) es much\u00edsimo m\u00e1s estricto. Solo deja pasar un objeto a la vez y se puede filtrar poniendo un $(item)Marco$(0) en uno de sus lados.");
		both("botania.page.livingwoodFunnel1", "One at a time, please", "De uno en uno, por favor");
		both("botania.entry.toolbelt", "Botanist's Toolbelt", "Cintur\u00f3n de herramientas del bot\u00e1nico");
		both("botania.tagline.toolbelt", "12 stacks of at-the-ready storage", "12 pilas de almacenamiento a mano");
		both("botania.page.toolbelt0", "The $(item)Botanist's Toolbelt$(0) is an easy-access extra inventory. By sneaking and looking at the horizon, you gain access to 12 extra stacks of storage, which can be used by right clicking the air in the direction where they appear. Any blocks in it will also provide for the $(item)Rod of the Shifting Crust$(0).$(p)It is worn on the belt slot.", "El $(item)Cintur\u00f3n de herramientas del bot\u00e1nico$(0) es un inventario extra de acceso r\u00e1pido. Si te agachas y miras al horizonte, obtienes 12 pilas extra de almacenamiento, que se usan haciendo clic derecho al aire en la direcci\u00f3n donde aparecen. Los bloques que guarde tambi\u00e9n abastecen a la $(item)Vara de la corteza deslizante$(0).$(p)Se lleva en la ranura de cintur\u00f3n.");
		both("botania.page.toolbelt1", "Not quite hammerspace", "No es exactamente un bolsillo m\u00e1gico");
		both("botania.entry.manasealCreeper", "Manaseal Creepers", "Creepers sellaman\u00e1");
		both("botania.tagline.manasealCreeper", "A walking rift in the mana flow", "Una grieta andante en el flujo de man\u00e1");
		both("botania.page.manasealCreeper0", "The $(thing)Manatide$(0) flows throughout the world, but as with a river, there are always bumps and rapids. The $(item)Manaseal Creeper$(0) is a walking rift in the flow of $(thing)Mana$(0). Should it explode near you, you'll find yourself stricken with a $(thing)Manatide Storm$(0), which will eat away at your mana, taking away what could be hours of generation. It's recommended to stay away from them at all costs.", "La $(thing)marea de man\u00e1$(0) fluye por todo el mundo, pero como en un r\u00edo, siempre hay baches y r\u00e1pidos. El $(item)Creeper sellaman\u00e1$(0) es una grieta andante en el flujo de $(thing)man\u00e1$(0). Si explota cerca de ti, te azotar\u00e1 una $(thing)Tormenta de la marea de man\u00e1$(0) que devorar\u00e1 tu man\u00e1 y se llevar\u00e1 lo que podr\u00edan ser horas de generaci\u00f3n. Es mejor mantenerse alejado de ellos a toda costa.");
		both("botania.page.manasealCreeper1", "However, they do have one interesting property. They crystallize their mana inside, occasionally resulting in a $(item)Black Lotus$(0) found on their corpse. Their storming energy, combined with this crystallized mana, can react with fully-formed $(item)Loti$(0). When a $(thing)Manatide Storm$(0) comes into contact with a $(item)Black Lotus$(0), it will break their harmony and result in a $(item)Wilted Lotus$(0), a powerful magical resource.", "Aun as\u00ed, tienen una propiedad interesante: cristalizan su man\u00e1 por dentro y a veces dejan un $(item)Loto negro$(0) en su cad\u00e1ver. Su energ\u00eda tormentosa, junto con ese man\u00e1 cristalizado, puede reaccionar con los $(item)Lotos$(0) ya formados. Cuando una $(thing)Tormenta de la marea de man\u00e1$(0) toca un $(item)Loto negro$(0), rompe su armon\u00eda y lo convierte en un $(item)Loto marchito$(0), un poderoso recurso m\u00e1gico.");
		both("botania.entry.clericalColorizer", "Clerical Colorization", "Colorizaci\u00f3n clerical");
		both("botania.tagline.clericalColorizer", "Colorful magic", "Magia de colores");
		both("botania.page.clericalColorizer0", "The $(item)Clerical Colorizer$(0), the $(thing)Ring$(0) form of the $(item)Paintslinger's Lens$(0), can change even the color of magic. Wearing one will affect any clerically aligned abilities, like the $(item)Priestly Emblems$(0) and their rods, changing their color. They can also be crafted alongside another $(thing)Bauble$(0) much like $(item)Cosmetic Baubles$(0).", "El $(item)Colorizador clerical$(0), la forma de $(thing)anillo$(0) de la $(item)Lente de man\u00e1: Coloreante$(0), puede cambiar hasta el color de la magia. Llevarlo puesto afecta a las habilidades de afinidad clerical, como los $(item)Emblemas sacerdotales$(0) y sus varas, y cambia su color. Tambi\u00e9n se puede combinar con otro $(thing)abalorio$(0) igual que los $(item)Abalorios cosm\u00e9ticos$(0).");
		both("botania.page.clericalColorizer1", "Beware of the dark clerics", "Cuidado con los cl\u00e9rigos oscuros");
		both("botania.page.clericalColorizer2", "A colorizer can be dyed much like leather by combining it with dyes in a crafting table, and cleared by putting it in a crafting table on its own.", "Un colorizador se ti\u00f1e como el cuero, combin\u00e1ndolo con tintes en una mesa de crafteo, y se limpia poni\u00e9ndolo solo en la mesa de crafteo.");
		both("botania.page.clericalColorizer3", "Much like $(item)Cosmetic Baubles$(0), a $(item)Coat of Arms$(0) adds a touch of style to the baubles you wear. Worn as an $(thing)Amulet$(0), or crafted alongside another $(thing)Bauble$(0), it acts as a $(item)Clerical Colorizer$(0) with the colors of its flag, so you can declare your allegiance. It is made of eight $(item)Iridescent Leaves$(0) around some $(item)Mana String$(0).", "Igual que los $(item)Abalorios cosm\u00e9ticos$(0), un $(item)Escudo de armas$(0) da un toque de estilo a los abalorios que llevas. Llevado como $(thing)amuleto$(0), o crafteado junto a otro $(thing)abalorio$(0), act\u00faa como un $(item)Colorizador clerical$(0) con los colores de su bandera, para que declares tu lealtad. Se hace con ocho $(item)Hojas iridiscentes$(0) alrededor de un poco de $(item)Hilo infundido de man\u00e1$(0).");
		both("botania.entry.coatsOfArms", "Coats of Arms", "Escudos de armas");
		both("botania.entry.crysanthermum", "Crysanthermum", "Crisantermo");
		both("botania.tagline.crysanthermum", "Mana from temperature", "Man\u00e1 a partir de la temperatura");
		both("botania.page.crysanthermum0", "The $(item)Crysanthermum$(0) is a hardy flower that can survive in any climate. However, its mana generation isn't indifferent to the climate. By dropping $(item)Metamorphic Stone$(0) or $(item)Metamorphic Cobblestone$(0) next to it, you change its temperature.", "El $(item)crisantermo$(0) es una flor resistente que sobrevive en cualquier clima. Sin embargo, su generaci\u00f3n de man\u00e1 no es indiferente al clima. Si sueltas $(item)piedra metam\u00f3rfica$(0) o $(item)adoqu\u00edn metam\u00f3rfico$(0) a su lado, cambias su temperatura.");
		both("botania.page.crysanthermum1", "The closer its temperature is to the biome you're in, the more mana it will generate. The hotter or colder the biome the stone comes from, the hotter or colder the flower will be after eating that stone.$(p)A flower at a neutral temperature generates nothing, and neither does one that becomes too cold or too hot, until it gets back to a normal temperature. Left alone it drifts back to neutral by one step every 30 seconds.", "Cuanto m\u00e1s se acerque su temperatura a la del bioma en que est\u00e1s, m\u00e1s man\u00e1 generar\u00e1. Cuanto m\u00e1s caliente o fr\u00edo sea el bioma del que viene la piedra, m\u00e1s caliente o fr\u00eda quedar\u00e1 la flor tras comerla.$(p)Una flor a temperatura neutra no genera nada, y tampoco una que se enfr\u00ede o se caliente demasiado, hasta que vuelva a una temperatura normal. Si la dejas sola, vuelve a la neutra un paso cada 30 segundos.");
		both("botania.page.crysanthermum2", "There are, however, a few caveats.$(p)Feeding the flower $(item)Fungal$(0) stone can do anything, from cooling the flower rapidly to heating it up immensely.$(p)Using a stone that was eaten within the last eight gives you diminishing returns, meaning that you'll occasionally have to course-correct. A $(item)Redstone Comparator$(0) reads its temperature.", "Pero hay algunas salvedades.$(p)Darle piedra $(item)f\u00fangica$(0) puede hacer cualquier cosa, desde enfriar la flor r\u00e1pidamente hasta calentarla much\u00edsimo.$(p)Usar una piedra que se comi\u00f3 entre las \u00faltimas ocho da rendimientos decrecientes, as\u00ed que de vez en cuando tendr\u00e1s que corregir el rumbo. Un $(item)comparador de redstone$(0) lee su temperatura.");
		both("botania.page.crysanthermum3", "Left by a Fortanono", "Dejada por un Fortanono");
		both("botania.entry.asgardandelion", "Asgardandelion", "Asgardiente de le\u00f3n");
		both("botania.tagline.asgardandelion", "Mana beyond measure", "Man\u00e1 sin medida");
		both("botania.page.asgardandelion0", "The $(item)Asgardandelion$(0) is a generating flower that makes an absurd amount of mana: $(thing)1,000,000$(0) mana every single tick by default. It needs no fuel, no pollination and no upkeep, and it never wilts.", "El $(item)asgardiente de le\u00f3n$(0) es una flor generadora que produce una cantidad absurda de man\u00e1: $(thing)1.000.000$(0) de man\u00e1 en cada tick por defecto. No necesita combustible, ni polinizaci\u00f3n, ni mantenimiento, y nunca se marchita.");
		both("botania.page.asgardandelion1", "It stores one tick of production and hands it to the $(item)Mana Spreader$(0) or $(item)Mana Pool$(0) it is bound to, so one flower fills a whole pool every tick and everything beyond that is wasted. The amount per tick can be changed, or the flower switched off, in the $(thing)asgardandelion$(0) section of $(thing)botania-common.toml$(0).", "Guarda un tick de producci\u00f3n y se lo entrega al $(item)esparcidor de man\u00e1$(0) o a la $(item)piscina de man\u00e1$(0) a la que est\u00e1 enlazada, as\u00ed que una sola flor llena una piscina entera en cada tick y todo lo que sobre se pierde. La cantidad por tick se puede cambiar, o la flor se puede apagar, en la secci\u00f3n $(thing)asgardandelion$(0) de $(thing)botania-common.toml$(0).");
		both("botania.page.asgardandelion2", "It is made on a $(l:basics/terrasteel)$(item)Terrestrial Agglomeration Plate$(0) from a $(l:generating_flowers/wither_mana_rose)$(item)Wither Mana Rose$(0), a Dandelion, 8 $(item)Gaia Spirits$(0), 4 $(item)Terrasteel Blocks$(0) and 4 $(item)Dragonstone Blocks$(0), and it takes 1,000,000 mana. Combine it with any $(item)Floating Flower$(0) to get a floating one.", "Se hace en una $(l:basics/terrasteel)$(item)placa de aglomeraci\u00f3n terrestre$(0) con una $(l:generating_flowers/wither_mana_rose)$(item)rosa de man\u00e1 wither$(0), un diente de le\u00f3n, 8 $(item)esp\u00edritus de Gaia$(0), 4 $(item)bloques de terracero$(0) y 4 $(item)bloques de piedra del drag\u00f3n$(0), y cuesta 1.000.000 de man\u00e1. Comb\u00ednala con cualquier $(item)flor flotante$(0) para obtener una flotante.");
		same("botania.entry.avaritiaTable", "Re-Avaritia Recipes");
		both("botania.tagline.avaritiaTable", "Creative objects on the Extreme Crafting Table", "Objetos creativos en la mesa de crafteo extrema");
		both("botania.page.avaritiaTable0", "When $(thing)Re-Avaritia$(0) is installed, the Creative Crafting module also adds recipes for its $(item)Extreme Crafting Table$(0) (the 9x9 table, tier 4). They use only Botania ingredients and come on top of the $(l:basics/terrasteel)$(item)Terrestrial Agglomeration Plate$(0)$(/l) recipes, which keep working.", "Cuando $(thing)Re-Avaritia$(0) está instalado, el módulo de crafteo creativo también añade recetas para su $(item)mesa de crafteo extrema$(0) (la mesa 9x9, nivel 4). Usan solo ingredientes de Botania y se suman a las recetas de la $(l:basics/terrasteel)$(item)placa de aglomeración terrestre$(0)$(/l), que siguen funcionando.");
		both("botania.page.avaritiaTable1", "$(item)Creative Mana Pool$(0): 9x9, terrasteel blocks on the rim, $(item)Gaia Spirits$(0), $(item)Mana Pools$(0), $(item)Dragonstone Blocks$(0) and a column of $(item)Fabulous Pools$(0) around a $(item)Mana Tablet$(0).$(p)$(item)Creative Mana Tablet$(0): 9x9, the eight sin runes, the relics ($(item)Odin Ring$(0), $(item)Thor Ring$(0), $(item)King Key$(0), $(item)Flugel Eye$(0), $(item)Flügel Tiara$(0) and more), four $(item)Mana Mirrors$(0), $(item)Fabulous Pools$(0) and a $(item)Mana Tablet$(0).", "$(item)Piscina de maná creativa$(0): 9x9, bloques de terracero en el borde, $(item)espíritus de Gaia$(0), $(item)piscinas de maná$(0), $(item)bloques de piedra dragón$(0) y una columna de $(item)piscinas fabulosas$(0) alrededor de una $(item)tableta de maná$(0).$(p)$(item)Tableta de maná creativa$(0): 9x9, las ocho runas de pecados, las reliquias ($(item)anillo de Odin$(0), $(item)anillo de Thor$(0), $(item)llave del rey$(0), $(item)ojo de Flugel$(0), $(item)tiara de los Flügel$(0) y más), cuatro $(item)espejos de maná$(0), $(item)piscinas fabulosas$(0) y una $(item)tableta de maná$(0).");
		both("botania.page.avaritiaTable2", "$(item)Creative Corporea Spark$(0): 5x5, a $(item)Master Corporea Spark$(0) in the centre with $(item)Gaia Spirits$(0), $(item)Pixie Dust$(0), $(item)Elementium Blocks$(0) and a $(item)Rune of Mana$(0).$(p)$(item)Infrangible Platform$(0) (x4): 3x3, $(item)Terrasteel Blocks$(0) in the corners, $(item)Abstruse Platforms$(0) on the sides and a $(item)Dragonstone Block$(0) in the middle.", "$(item)Chispa de corporea creativa$(0): 5x5, una $(item)chispa maestra de corporea$(0) en el centro con $(item)espíritus de Gaia$(0), $(item)polvo de píxie$(0), $(item)bloques de elementium$(0) y una $(item)runa de maná$(0).$(p)$(item)Plataforma irrompible$(0) (x4): 3x3, $(item)bloques de terracero$(0) en las esquinas, $(item)plataformas abstrusas$(0) en los lados y un $(item)bloque de piedra dragón$(0) en el centro.");
	}

