		both("botania.jade.redstone_disabled", "Disabled by redstone", "Desactivada por redstone");
		both("botania.jade.spark.augment", "Augment: %s", "Aumento: %s");
		both("botania.jade.spark.network", "Network: %s", "Red: %s");
		both("botania.jade.streak", "Streak: %s", "Racha: %s");
