		same("config.jade.plugin_botania", "Botania");
		both("config.jade.plugin_botania.alfheim_portal", "Portal to Alfheim", "Portal a Alfheim");
		both("config.jade.plugin_botania.brewery", "Botanical Brewery", "Destiler\u00eda bot\u00e1nica");
		both("config.jade.plugin_botania.compact_numbers", "Compact Numbers", "N\u00fameros compactos");
		both("config.jade.plugin_botania.compact_numbers_desc", "Shorten big numbers, for example 314.2k instead of 314240", "Abrevia los n\u00fameros grandes, por ejemplo 314.2k en vez de 314240");
		both("config.jade.plugin_botania.enabled", "Botania Tooltips", "Informaci\u00f3n de Botania");
		both("config.jade.plugin_botania.enabled_desc", "Master switch for every Botania mana tooltip", "Interruptor general de toda la informaci\u00f3n de man\u00e1 de Botania");
		both("config.jade.plugin_botania.functional_flower", "Functional Flowers", "Flores funcionales");
		both("config.jade.plugin_botania.generating_flower", "Generating Flowers", "Flores generadoras");
		both("config.jade.plugin_botania.generating_flower.timers", "Timers", "Temporizadores");
		both("config.jade.plugin_botania.generating_flower.timers_desc", "Burn time, cooldowns, digestion, decay and streaks", "Tiempo de combusti\u00f3n, enfriamientos, digesti\u00f3n, marchitado y rachas");
		both("config.jade.plugin_botania.mana_bar_color", "Mana Bar Color", "Color de la barra de man\u00e1");
