		both("config.jade.plugin_botania.mana_enchanter", "Mana Enchanter", "Encantador de man\u00e1");
		both("config.jade.plugin_botania.mana_pool", "Mana Pools", "Reservas de man\u00e1");
		both("config.jade.plugin_botania.mana_pool.recipe", "Mana Infusion Preview", "Vista previa de infusi\u00f3n");
		both("config.jade.plugin_botania.mana_pool.recipe_desc", "Show the infusion result of the held item", "Muestra el resultado de infusi\u00f3n del objeto en la mano");
		both("config.jade.plugin_botania.mana_spark", "Mana Sparks", "Chispas de man\u00e1");
		both("config.jade.plugin_botania.mana_spreader", "Mana Spreaders", "Esparcidores de man\u00e1");
		both("config.jade.plugin_botania.mana_storage", "Other Mana Blocks", "Otros bloques con man\u00e1");
		both("config.jade.plugin_botania.mana_storage_desc", "Livingwood Avatar and Life Imbuer", "Avatar de madera viva e imbuidor de vida");
		both("config.jade.plugin_botania.native_colors", "Use Block Colors", "Usar colores de los bloques");
		both("config.jade.plugin_botania.native_colors_desc", "Color mana bars like the Wand of the Forest HUD (flower and spreader colors) instead of the custom color", "Colorea las barras como el HUD de la Vara del Bosque (colores de flores y esparcidores) en vez del color personalizado");
		both("config.jade.plugin_botania.petal_apothecary", "Petal Apothecary", "Boticario de p\u00e9talos");
